// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-06-share-dialog-text-and-payload.spec.ts, план .qa/e2e/specs/guided-prayer.md, кейс .qa/tests/guided-prayer/GP-06-share-prayer-button.md
// Тикет #6a86f7df · 6a86f7df6f29cb4c367083d2 «עיצוב מוקאפ: תפילה מודרכת — קטע בתוך סדר התפילה». Опора: мокап S-17 (Figma 608:1726), окно предпросмотра.
// Перенесено окно предпросмотра и «ביטול». Что уходит в системное «Поделиться» после «המשך לשיתוף» (web: подмена navigator.share) —
// в приложении это системный лист, текст не перехватывается: «המשך לשיתוף» здесь НЕ нажимается (см. COVERAGE-prayer.md, ручная проверка).
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabel, byLabelStartsWith, tapText, tapLabel, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { openPrayer, openRoute, hasDeepLinks, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

async function switchNusach(title: string, to: 'ספרדי' | 'אשכנזי') {
  await (await byLabelStartsWith('בחירת נוסח')).click();
  await tapText(to);
  const replace = await byText('החלף');
  if (await replace.isDisplayed().catch(() => false)) await replace.click();
  await expectVisibleText(`${title} (${to})`);
}

/** Окно «שיתוף התפילה»: заголовок, пояснение, текст и ссылка, кнопки; «ביטול» закрывает окно. */
async function checkShareDialog(key: string, prayerName: string) {
  const text = `מצטרפים להתפלל ${prayerName} באפליקציית אור הגאולה?`;
  const url = `https://zichui-harabim.expo.app/prayer/${key}`;
  const share = await byLabel('שיתוף התפילה');
  if (!(await share.isDisplayed().catch(() => false))) await scrollToText('האזן להקראה');
  await tapLabel('שיתוף התפילה');
  await expect(byText('שיתוף התפילה')).toBeDisplayed();
  await expect(byTextContains('זו ההודעה שתישלח, בלי שום פרט נוסף:')).toBeDisplayed();
  await expect(byTextContains(text)).toBeDisplayed();
  await expect(byTextContains(url)).toBeDisplayed();
  await expectVisibleText('ביטול');
  await expectVisibleText('המשך לשיתוף');
  await tapText('ביטול');
  await expect(byTextContains('זו ההודעה שתישלח')).not.toBeDisplayed();
  await expect(byText('המשך לשיתוף')).not.toBeDisplayed();
}

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  it('GP-06 Окно «שיתוף התפילה»: текст и ссылка, «ביטול» закрывает — מנחה ספרד и ערבית אשכנז #6a86f7df @prod-safe', async () => {
    // 1. מנחה (ספרדי), «1 מתוך 11» → окно предпросмотра.
    if (hasDeepLinks()) await openRoute('/prayer/mincha_sfarad');
    else { await openPrayer('mincha_ashkenaz', 'מנחה'); await switchNusach('מנחה', 'ספרדי'); }
    await (await byTextMatches('\\d+ מתוך \\d+')).waitForDisplayed();
    await goToPage(1, 11);
    await checkShareDialog('mincha_sfarad', 'מנחה');
    if (!hasDeepLinks()) await switchNusach('מנחה', 'אשכנזי');

    // 2. ערבית (אשכנזי), первый קטע — имя молитвы из шапки до « (».
    await toHome();
    await openPrayer('arvit_ashkenaz', 'ערבית');
    const header = await (await byTextMatches('ערבית \\(.+\\)')).getText();
    const name = header.split(' (')[0];
    expect(name).toBe('ערבית');
    await goToPage(1, 15);
    await checkShareDialog('arvit_ashkenaz', name);
  });
});
